-- Views and materialized views
-- Generated by scripts/snapshot-schema.mts from the live database. Do not edit by hand;
-- change the database, then re-run the script.

create or replace view public.leaderboard_achievements as
 SELECT p.id AS user_id,
    p.username,
    count(ua.achievement_key)::integer AS score
   FROM profiles p
     LEFT JOIN user_achievements ua ON ua.user_id = p.id
  WHERE p.username IS NOT NULL AND NOT p.is_admin
  GROUP BY p.id, p.username;

create materialized view if not exists public.leaderboard_blackjack as
 WITH running AS (
         SELECT blackjack_hands.user_id,
            blackjack_hands.settled_at,
            sum(blackjack_hands.net_delta) OVER (PARTITION BY blackjack_hands.user_id ORDER BY blackjack_hands.settled_at, blackjack_hands.id) AS cum
           FROM blackjack_hands
          WHERE blackjack_hands.status = 'settled'::text AND blackjack_hands.net_delta IS NOT NULL AND blackjack_hands.settled_at IS NOT NULL
        ), totals AS (
         SELECT blackjack_hands.user_id,
            sum(blackjack_hands.net_delta)::integer AS score
           FROM blackjack_hands
          WHERE blackjack_hands.status = 'settled'::text AND blackjack_hands.net_delta IS NOT NULL AND blackjack_hands.settled_at IS NOT NULL
          GROUP BY blackjack_hands.user_id
        ), reached AS (
         SELECT t.user_id,
            t.score,
            ( SELECT min(r.settled_at) AS min
                   FROM running r
                  WHERE r.user_id = t.user_id AND r.cum >= t.score) AS created_at
           FROM totals t
        )
 SELECT p.id AS user_id,
    p.username,
    reached.score,
    reached.created_at
   FROM profiles p
     JOIN reached ON reached.user_id = p.id
  WHERE p.username IS NOT NULL AND NOT p.is_admin;

create or replace view public.leaderboard_bounty_points as
 SELECT id AS user_id,
    username,
    COALESCE(bounty_points, 0) AS score,
    created_at
   FROM profiles
  WHERE username IS NOT NULL AND NOT is_admin;

create or replace view public.leaderboard_collection as
 SELECT p.id AS user_id,
    p.username,
    count(DISTINCT uc.card_variant_id)::integer AS score
   FROM profiles p
     LEFT JOIN user_collection uc ON uc.user_id = p.id
  WHERE p.username IS NOT NULL AND NOT p.is_admin
  GROUP BY p.id, p.username;

create materialized view if not exists public.leaderboard_den as
 WITH events AS (
         SELECT blackjack_hands.user_id,
            blackjack_hands.settled_at AS ts,
            blackjack_hands.net_delta AS delta
           FROM blackjack_hands
          WHERE blackjack_hands.status = 'settled'::text AND blackjack_hands.net_delta IS NOT NULL AND blackjack_hands.settled_at IS NOT NULL
        UNION ALL
         SELECT slot_spins.user_id,
            slot_spins.created_at AS ts,
            slot_spins.payout - slot_spins.wager AS delta
           FROM slot_spins
        UNION ALL
         SELECT roulette_spins.user_id,
            roulette_spins.created_at AS ts,
            roulette_spins.net_chips AS delta
           FROM roulette_spins
        ), running AS (
         SELECT events.user_id,
            events.ts,
            sum(events.delta) OVER (PARTITION BY events.user_id ORDER BY events.ts) AS cum
           FROM events
        ), totals AS (
         SELECT events.user_id,
            sum(events.delta)::integer AS score
           FROM events
          GROUP BY events.user_id
        ), reached AS (
         SELECT t.user_id,
            t.score,
            ( SELECT min(r.ts) AS min
                   FROM running r
                  WHERE r.user_id = t.user_id AND r.cum >= t.score) AS created_at
           FROM totals t
        )
 SELECT p.id AS user_id,
    p.username,
    reached.score,
    reached.created_at
   FROM profiles p
     JOIN reached ON reached.user_id = p.id
  WHERE p.username IS NOT NULL AND NOT p.is_admin;

create or replace view public.leaderboard_dons_gauntlet as
 SELECT id AS user_id,
    username,
    dons_gauntlet_best_depth AS score,
    dons_gauntlet_best_depth_ms AS time_ms,
    dons_gauntlet_best_depth_at AS created_at
   FROM profiles p
  WHERE dons_gauntlet_best_depth > 0 AND is_admin = false AND username IS NOT NULL;

create or replace view public.leaderboard_dons_gauntlet_hardcore as
