create or replace view public.leaderboard_exchange as
 SELECT b.user_id,
    p.username,
    sum(COALESCE(b.payout, 0)) - sum(b.stake) AS score,
    max(b.settled_at) AS created_at
   FROM exchange_bets b
     JOIN profiles p ON p.id = b.user_id
  WHERE b.status <> 'open'::text AND COALESCE(p.is_admin, false) = false
  GROUP BY b.user_id, p.username
 HAVING count(*) > 0;

create or replace view public.leaderboard_exchange_week as
 SELECT b.user_id,
    p.username,
    sum(COALESCE(b.payout, 0)) - sum(b.stake) AS score,
    max(b.settled_at) AS created_at
   FROM exchange_bets b
     JOIN profiles p ON p.id = b.user_id
  WHERE b.status <> 'open'::text AND b.settled_at >= date_trunc('week'::text, now()) AND COALESCE(p.is_admin, false) = false
  GROUP BY b.user_id, p.username
 HAVING count(*) > 0;

